sys_script_fix.script:
var _page = new GlideRecord("sys_cs_adapter_configuration_page");
_page.query();
while (_page.next()) {
	var client_type = _page.client_type;
	if (client_type == 'workplace')
		client_type = 'facebook';
	var configStr = new sn_cs_adapter.AdapterConfigGenerator().getDefaultConfig(client_type);
	var defaultConfig = JSON.parse(configStr);
	var adapter_config = new GlideRecord("sys_cs_adapter_configuration");
	adapter_config.addQuery("sys_cs_adapter_configuration_page", _page.sys_id);
	adapter_config.query();
	var adapter_config_dict=[];
	while (adapter_config.next()) {
		adapter_config_dict.push({
			key:   adapter_config.attribute_name.trim(),
			value: adapter_config.attribute_value.trim()
		});
	}

	//Start Of insert newly created record in sys_cs_adapter_configuration_page to sys_cs_adapter_configuration
	for( var akey in defaultConfig ){
		var oldAttribute =false;
		for (var i = 0; i < adapter_config_dict.length; i++) {
			if(akey.equals(adapter_config_dict[i].key))
				{
				oldAttribute=true;
				break;
			}
		}
		if(!oldAttribute)
			{
			var newAttribute = new GlideRecord("sys_cs_adapter_configuration");
			newAttribute.initialize();
			newAttribute.setValue('sys_cs_adapter_configuration_page', _page.sys_id);
			newAttribute.setValue('attribute_name', akey);
			newAttribute.setValue('attribute_value', defaultConfig[akey]);
			newAttribute.insert();
		}
	}
	//End Of insert newly created record in sys_cs_adapter_configuration_page to sys_cs_adapter_configuration


	//Start Of Updating  newly introduced  messages  which customer didn't update from sys_cs_adapter_configuration_page to sys_cs_adapter_configuration

	adapter_config.addQuery("sys_cs_adapter_configuration_page", _page.sys_id);
	adapter_config.query();
	while (adapter_config.next()) {
		var name = adapter_config.attribute_name.trim();
		var value = adapter_config.attribute_value.trim();
		if((name.equals("link_account_success_msg") && value.equals("You have successfully linked your ServiceNow account.")) ||
		(name.equals("link_account_label") && value.equals("Connect to ServiceNow"))||
		(name.equals("greeting_msg") && value.equals("Welcome to the ServiceNow platform."))||
		(name.equals("pick_month_msg") && value.equals("Which month would you like to change it to? (Please make a selection or type it in.)"))||
		(name.equals("invalid_month_please_provide_valid_month") && value.equals("Sorry. I didn't understand the month you entered. Please try again using this format MM or mon."))||
		(name.equals("invalid_time_please_provide_valid_time") && value.equals("Sorry. I didn't understand the time you entered. Please try again using this format (HH:MM AM/PM)."))||
		(name.equals("invalid_day_please_provide_valid_day") && value.equals("Sorry. I didn't understand the day you entered. Please try again using this format (dd)."))||
		(name.equals("invalid_year_please_provide_valid_year") && value.equals("Sorry. I didn't understand the year you entered. Please try again using this format (yyyy).")) ||
		(name.equals("link_account_msg") && value.equals("How can I help you?  Please enter your request or create a link with your ServiceNow account.")) ||
		(name.equals("link_account_success_msg") && value.equals("Thanks for linking your account!"))||
		(name.equals("end_chat_msg") && value.equals("You can type %s any time when you want to leave the chat."))||
		(name.equals("topic_picker_title") && value.equals("Hi %s, please enter your request or make a selection of what I can help with.  You can type %s any time when you need help."))||
		(name.equals("msteams_welcome_part1_msg") && value.equals("Hello!  I'm Now Virtual Agent. I'm here to help you.<br/><br/>To get started, type <b>$help_keyword</b>.")))
		{
			adapter_config.attribute_value=defaultConfig[name];
		}
		adapter_config.update();
	}
	//End Of Updating  newly introduced  messages  which customer didn't update from sys_cs_adapter_configuration_page to sys_cs_adapter_configuration

	//Start of deleting unused record in sys_cs_adapter_configuration
	adapter_config.addQuery("sys_cs_adapter_configuration_page", _page.sys_id);
	adapter_config.query();
	while (adapter_config.next()) {
		var name = adapter_config.attribute_name.trim();
		var value = adapter_config.attribute_value.trim();
		if(name.equals("carousel_next_placeholder_text") || name.equals("choice_formatter") || name.equals("topic_picker_title") || name.equals("inputImageExceptOneMsg") || name.equals("msteams_welcome_msg_part1")|| name.equals("show_me_everything_title") || name.equals("fb_welcome_msg_part1")|| name.equals("fb_welcome_msg_part2"))
			{
				adapter_config.deleteRecord();
			}
		}
	//End of delete
}
